-- LOCAL ONLY. Monthly factual conference; HR27 informative HE; no salaries, money or external payroll.
BEGIN;SET LOCAL lock_timeout='10s';SET LOCAL search_path=pg_catalog;LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;SELECT pg_advisory_xact_lock(61001,1);LOCK TABLE public.folha_registos,public.folha_he,public.folha_historico,public.folha_gestao_historico,public.folha_avaliacoes_diarias,public.folha_jornadas_individuais_versoes,public.folha_config_empresa,public.colaboradores,public.ausencias,public.folha_vencimentos,public.quadro_pessoal_movimentos,public.quadro_equipa_permanencias,folha_privado.operacoes IN SHARE ROW EXCLUSIVE MODE;
DO $hours_dependencies$ BEGIN
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.ator()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='176c4fb030401fb45c89f3cd1616a9d26e9e15b691ff524a33dfc8d233c6b079' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.ator()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.obra(uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='731f5289cd29bdb7f7d69723fabb76cbb8b8e577bb474c679f991c7271d9788e' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.obra(uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.lock_dia(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b29022304f316e25dd34bae7a1e1906a0dfd72bd041a1d658338cc8394745502' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.lock_dia(uuid,date)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.local(uuid,uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='9eb2f0d8b7e52d5280f0798c48cb8ec84377281c1e13706bc066b1cf3765070b' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.local(uuid,uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_contexto_v2(date,uuid)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='e5ca6e224708a655a9c778fa6a5701b39e6c0aab8dbf0a01a87ffb77d42ea095' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner AND x.grantee<>'authenticated'::regrole)) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: public.fn_folha_contexto_v2(date,uuid)';END IF;
END $hours_dependencies$;DO $base$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_conferencia_contexto_v3(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='3c66b79ac1882a756ccd430fa403e5c4c195c195e8ddb77ae7699dc80b78ee6c' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: public.fn_folha_conferencia_contexto_v3(uuid,date)';END IF;
END $base$;
DO $absent$ BEGIN IF to_regclass('public.folha_conferencias_mensais') IS NOT NULL OR to_regclass('public.folha_conferencia_historico') IS NOT NULL OR to_regprocedure('folha_privado.conferencia_calcular(uuid,date)') IS NOT NULL OR to_regprocedure('folha_privado.conferencia_guardar()') IS NOT NULL OR to_regprocedure('folha_privado.conferencia_historico_guardar()') IS NOT NULL OR to_regprocedure('folha_privado.conferencia_trilho_final()') IS NOT NULL OR to_regprocedure('folha_privado.conferencia_reconciliar()') IS NOT NULL OR to_regprocedure('public.fn_folha_conferencia_v3(text,jsonb,boolean,text)') IS NOT NULL THEN RAISE EXCEPTION 'MONTHLY_PRESENT_OR_PARTIAL';END IF;END $absent$;
DO $data$ DECLARE r record;j jsonb;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='primeline_monthly_backup' AND nspowner='postgres'::regrole) OR EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) x WHERE n.nspname='primeline_monthly_backup' AND x.grantee<>n.nspowner) OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x WHERE n.nspname='primeline_monthly_backup' AND x.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='primeline_monthly_backup' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL AND a.attacl<>'{}'::aclitem[]) THEN RAISE EXCEPTION 'MONTHLY_BACKUP_NOT_PRIVATE';END IF;
FOR r IN SELECT * FROM primeline_monthly_backup.dados LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),''[]''::jsonb) FROM %s x',r.tabela::regclass) INTO j;IF j IS DISTINCT FROM r.linhas THEN RAISE EXCEPTION 'MONTHLY_DATA_DRIFT';END IF;END LOOP;END $data$;
-- Internal monthly conference only. No daily approval, hourly price, payment or external payroll.
CREATE TABLE public.folha_conferencias_mensais(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id uuid NOT NULL REFERENCES public.empresas(id),colaborador_id uuid NOT NULL REFERENCES public.colaboradores(id),competencia date NOT NULL CHECK(isfinite(competencia) AND extract(day FROM competencia)=1),
 estado text NOT NULL CHECK(estado IN('conferida','devolvida','validada_para_integracao','requer_revalidacao')),revision integer NOT NULL CHECK(revision>0),
 referencias jsonb NOT NULL CHECK(jsonb_typeof(referencias)='object'),snapshot jsonb NOT NULL CHECK(jsonb_typeof(snapshot)='object'),fingerprint text NOT NULL CHECK(fingerprint ~ '^[0-9a-f]{64}$'),
 pedidos_correcao jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(pedidos_correcao)='array'),validacao_fingerprint text CHECK(validacao_fingerprint ~ '^[0-9a-f]{64}$'),validado_por uuid REFERENCES public.utilizadores(id),validado_em timestamptz,
 criado_por uuid NOT NULL REFERENCES public.utilizadores(id),atualizado_por uuid NOT NULL REFERENCES public.utilizadores(id),criado_em timestamptz NOT NULL DEFAULT now(),atualizado_em timestamptz NOT NULL DEFAULT now(),ultimo_request_id uuid NOT NULL,
 UNIQUE(empresa_id,colaborador_id,competencia),CHECK(num_nonnulls(validacao_fingerprint,validado_por,validado_em) IN(0,3)),CHECK(estado<>'validada_para_integracao' OR (num_nonnulls(validacao_fingerprint,validado_por,validado_em)=3 AND validacao_fingerprint IS NOT DISTINCT FROM fingerprint))
);CREATE TABLE public.folha_conferencia_historico(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id uuid NOT NULL REFERENCES public.empresas(id),conferencia_id uuid NOT NULL REFERENCES public.folha_conferencias_mensais(id),revision integer NOT NULL CHECK(revision>0),action text NOT NULL CHECK(action IN('conferir','devolver','validar','source_change')),
 antes jsonb,depois jsonb NOT NULL,ator_id uuid NOT NULL REFERENCES public.utilizadores(id),at timestamptz NOT NULL DEFAULT now(),request_id uuid NOT NULL,reason text CHECK(length(reason)<=1000),UNIQUE(conferencia_id,revision)
);
ALTER TABLE public.folha_conferencias_mensais ENABLE ROW LEVEL SECURITY;ALTER TABLE public.folha_conferencia_historico ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.folha_conferencias_mensais,public.folha_conferencia_historico FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION folha_privado.conferencia_calcular(p uuid,m date) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $calculate$
DECLARE u public.utilizadores;c public.colaboradores;cfg public.folha_config_empresa;old public.folha_conferencias_mensais;ev public.folha_avaliacoes_diarias;ref jsonb;refs jsonb:='{}';s jsonb;f jsonb;ab jsonb;hs jsonb;pend jsonb:='[]';days jsonb:='[]';d date;limit_date date;worked integer;expected integer;total_actual integer:=0;total_known integer:=0;unknown integer:=0;credited integer:=0;absence_pending boolean;has_absence boolean;open_day boolean;
BEGIN
 u:=folha_privado.ator();SELECT * INTO c FROM public.colaboradores WHERE id=p AND empresa_id=u.empresa_id;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: colaborador' USING ERRCODE='42501';END IF;
 IF m IS NULL OR NOT isfinite(m) OR extract(day FROM m) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'MONTH_REQUIRED';END IF;
 SELECT * INTO cfg FROM public.folha_config_empresa WHERE empresa_id=u.empresa_id;SELECT * INTO old FROM public.folha_conferencias_mensais WHERE empresa_id=u.empresa_id AND colaborador_id=p AND competencia=m;
 limit_date:=(m+interval '1 month')::date;d:=greatest(m,c.data_admissao);IF c.data_admissao IS NULL THEN pend:=pend||jsonb_build_array(jsonb_build_object('reason','admissao_por_confirmar'));d:=m;END IF;
 IF NOT coalesce(cfg.calendar_complete,false) OR NOT extract(year FROM m)::integer=ANY(coalesce(cfg.calendar_validated_years,'{}')) THEN pend:=pend||jsonb_build_array(jsonb_build_object('reason','calendario_por_confirmar'));END IF;
 WHILE d<limit_date AND (c.data_saida IS NULL OR d<c.data_saida) LOOP
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',x.id,'revision',x.revision,'work_id',x.obra_id,'intervals',x.intervals,'minutes',x.minutes,'state',x.estado,'special_day',x.special_day,'special_reviewed',x.special_reviewed_at IS NOT NULL) ORDER BY x.id::text COLLATE "C"),'[]'),coalesce(sum(x.minutes),0)::integer,coalesce(bool_or(x.estado='open'),false) INTO f,worked,open_day FROM public.folha_registos x WHERE x.empresa_id=u.empresa_id AND x.colaborador_id=p AND x.data=d;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'type',a.tipo,'state',a.estado) ORDER BY a.id::text COLLATE "C"),'[]'),coalesce(bool_or(a.estado='ausente_pendente'),false) INTO ab,absence_pending FROM public.ausencias a WHERE a.colaborador_id=p AND a.data=d;has_absence:=jsonb_array_length(ab)>0;
  SELECT * INTO ev FROM public.folha_avaliacoes_diarias WHERE empresa_id=u.empresa_id AND colaborador_id=p AND data=d;
  ref:=old.referencias->d::text;
  IF ref->>'referencia_estado' IS DISTINCT FROM 'capturada' OR ref->>'source'='daily_frozen' AND (ref->>'reference_revision')::integer IS DISTINCT FROM ev.referencia_revision THEN
   IF ev.referencia_estado='capturada' THEN ref:=jsonb_build_object('referencia_estado','capturada','expected_minutes',ev.expected_minutes,'reference_revision',ev.referencia_revision,'source','daily_frozen','evaluation_id',ev.id,'snapshot',ev.horario_snapshot);
   ELSIF cfg.avaliacao_diaria_data_ativacao IS NOT NULL THEN ref:=folha_privado.diaria_referencia(p,d);
   ELSE ref:=jsonb_build_object('referencia_estado','pendente','expected_minutes',NULL,'reason','mecanismo_diario_nao_ativado');END IF;
  END IF;
  IF d<=(now() AT TIME ZONE 'Europe/Lisbon')::date THEN refs:=refs||jsonb_build_object(d::text,ref);END IF;expected:=CASE WHEN ref->>'referencia_estado'='capturada' THEN (ref->>'expected_minutes')::integer END;total_actual:=total_actual+worked;
  IF expected IS NULL THEN unknown:=unknown+1;pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','referencia_diaria_pendente'));ELSE total_known:=total_known+expected;END IF;
  IF open_day THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','intervalo_aberto'));END IF;
  IF absence_pending THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','ausencia_por_classificar'));END IF;
  IF has_absence AND worked>0 THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','ausencia_com_horas'));
  ELSIF has_absence AND NOT absence_pending AND expected IS NOT NULL THEN credited:=credited+expected;
  ELSIF expected>worked AND NOT open_day AND d<=(now() AT TIME ZONE 'Europe/Lisbon')::date THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','horas_em_falta','minutes',expected-worked));END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(f) x WHERE x->>'state'='regularization' AND NOT coalesce(ev.ativa,false)) THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','factos_por_regularizar'));END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(f) x WHERE (x->>'special_day')::boolean AND NOT (x->>'special_reviewed')::boolean) THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','dia_especial_pendente'));END IF;
  IF ev.ativa AND ev.factos_fingerprint IS DISTINCT FROM encode(sha256(convert_to((folha_privado.diaria_factos(p,d)->'canonical')::text,'UTF8')),'hex') THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','avaliacao_por_reconciliar'));END IF;
 IF ev.ativa THEN
   IF ev.he_estado='pendente' THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','he_por_classificar'));END IF;
   IF EXISTS(SELECT 1 FROM unnest(ev.pendencias) x WHERE x NOT IN('he_validada_aguarda_processamento','he_diaria_pendente','horas_em_falta','referencia_diaria_pendente')) THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','avaliacao_diaria_pendente'));END IF;
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',h.id,'revision',h.revision,'state',h.estado,'minutes',h.minutes,'source_revision',h.folha_revision) ORDER BY h.id::text COLLATE "C"),'[]') INTO hs FROM public.folha_he h JOIN public.folha_registos x ON x.id=h.folha_id WHERE x.colaborador_id=p AND x.data=d AND h.empresa_id=u.empresa_id AND h.estado<>'superseded';
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(hs) h WHERE h->>'state' IN('potential','pending_validation','pending_rule')) THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','he_normal_por_classificar'));END IF;
  IF EXISTS(SELECT 1 FROM public.ponto_pessoal_obra x WHERE x.empresa_id=u.empresa_id AND x.colaborador_id=p AND x.data=d) THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','legado_por_reconciliar'));END IF;
  days:=days||jsonb_build_array(jsonb_build_object('date',d,'facts',f,'actual_minutes',worked,'expected_minutes',expected,'absence',ab,'normal_he',hs,'daily',CASE WHEN ev.id IS NULL THEN NULL ELSE jsonb_build_object('id',ev.id,'revision',ev.revision,'fingerprint',ev.factos_fingerprint,'reference_revision',ev.referencia_revision,'he_state',ev.he_estado,'he_quantity',ev.excedente_minutes,'decision_fingerprint',ev.decisao_fingerprint,'decided_by',ev.he_decidido_por,'decided_at',ev.he_decidido_em) END));d:=d+1;
 END LOOP;
 s:=jsonb_build_object('version','monthly_hr27_v1','company_id',u.empresa_id,'person_id',p,'month',m,'admission',c.data_admissao,'exit',c.data_saida,'calendar_complete',cfg.calendar_complete,'calendar_years',(SELECT array_agg(DISTINCT x ORDER BY x) FROM unnest(cfg.calendar_validated_years) x),'holiday_dates',(SELECT array_agg(DISTINCT x ORDER BY x) FROM unnest(cfg.holiday_dates) x),'references',refs,'days',days,'actual_minutes',total_actual,'known_expected_minutes',total_known,'expected_minutes',CASE WHEN unknown=0 THEN total_known END,'unknown_reference_days',unknown,'classified_absence_minutes',credited,'pending',pend,'he_policy','HR-27','financial_effect',false);
 RETURN s||jsonb_build_object('fingerprint',encode(sha256(convert_to(s::text,'UTF8')),'hex'));
END $calculate$;CREATE FUNCTION folha_privado.conferencia_guardar() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog AS $guard$
DECLARE u public.utilizadores;s jsonb;
BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'CONTROLLED_CONFERENCE_WRITER_REQUIRED' USING ERRCODE='42501';END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'CONFERENCE_HISTORY_IMMUTABLE';END IF;
 u:=folha_privado.ator();IF u.empresa_id IS DISTINCT FROM NEW.empresa_id OR NEW.atualizado_por IS DISTINCT FROM u.id THEN RAISE EXCEPTION 'CONFERENCE_TENANT_ACTOR_CONFLICT' USING ERRCODE='42501';END IF;
 IF TG_OP='INSERT' AND (NOT folha_privado.adm() OR NEW.criado_por<>u.id OR NEW.revision<>1) THEN RAISE EXCEPTION 'CONFERENCE_ADMIN_REQUIRED' USING ERRCODE='42501';END IF;
 IF TG_OP='UPDATE' AND (ROW(NEW.id,NEW.empresa_id,NEW.colaborador_id,NEW.competencia,NEW.criado_por,NEW.criado_em) IS DISTINCT FROM ROW(OLD.id,OLD.empresa_id,OLD.colaborador_id,OLD.competencia,OLD.criado_por,OLD.criado_em) OR NEW.revision<>OLD.revision+1) THEN RAISE EXCEPTION 'CONFERENCE_IDENTITY_REVISION_IMMUTABLE';END IF;
 IF TG_OP='UPDATE' AND NEW.estado<>'validada_para_integracao' AND ROW(NEW.validacao_fingerprint,NEW.validado_por,NEW.validado_em) IS DISTINCT FROM ROW(OLD.validacao_fingerprint,OLD.validado_por,OLD.validado_em) THEN RAISE EXCEPTION 'CONFERENCE_PREVIOUS_APPROVAL_IMMUTABLE';END IF;
 IF NEW.estado IN('conferida','devolvida','validada_para_integracao') AND NOT folha_privado.adm() THEN RAISE EXCEPTION 'CONFERENCE_ADMIN_REQUIRED' USING ERRCODE='42501';END IF;
 s:=folha_privado.conferencia_calcular(NEW.colaborador_id,NEW.competencia);
 IF NEW.fingerprint IS DISTINCT FROM s->>'fingerprint' OR NEW.snapshot IS DISTINCT FROM s OR NEW.referencias IS DISTINCT FROM s->'references' THEN RAISE EXCEPTION 'CONFERENCE_SOURCE_HASH_CONFLICT';END IF;
 IF NEW.estado='validada_para_integracao' AND (jsonb_array_length(s->'pending')>0 OR jsonb_array_length(NEW.pedidos_correcao)>0 OR (NEW.competencia+interval '1 month')::date>(now() AT TIME ZONE 'Europe/Lisbon')::date OR NEW.validado_por IS DISTINCT FROM u.id) THEN RAISE EXCEPTION 'CONFERENCE_PENDING';END IF;
 RETURN NEW;
END $guard$;
CREATE FUNCTION folha_privado.conferencia_historico_guardar() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog AS $history$
DECLARE u public.utilizadores;
BEGIN
 IF current_user<>'postgres' OR TG_OP<>'INSERT' THEN RAISE EXCEPTION 'CONFERENCE_HISTORY_IMMUTABLE' USING ERRCODE='42501';END IF;u:=folha_privado.ator();
 IF NEW.empresa_id IS DISTINCT FROM u.empresa_id OR NEW.ator_id IS DISTINCT FROM u.id OR NOT EXISTS(SELECT 1 FROM public.folha_conferencias_mensais c WHERE c.id=NEW.conferencia_id AND c.empresa_id=NEW.empresa_id AND c.revision=NEW.revision AND NEW.depois=to_jsonb(c) AND c.ultimo_request_id=NEW.request_id) THEN RAISE EXCEPTION 'CONFERENCE_HISTORY_CONFLICT';END IF;
 RETURN NEW;
END $history$;
CREATE FUNCTION folha_privado.conferencia_trilho_final() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $final$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.folha_conferencia_historico h WHERE h.conferencia_id=NEW.id AND h.empresa_id=NEW.empresa_id AND h.revision=NEW.revision AND h.request_id=NEW.ultimo_request_id AND h.depois=to_jsonb(NEW)) THEN RAISE EXCEPTION 'CONFERENCE_HISTORY_REQUIRED' USING ERRCODE='23514';END IF;RETURN NULL;
END $final$;
CREATE TRIGGER folha_conferencia_guardar BEFORE INSERT OR UPDATE OR DELETE ON public.folha_conferencias_mensais FOR EACH ROW EXECUTE FUNCTION folha_privado.conferencia_guardar();
CREATE TRIGGER folha_conferencia_historico_guardar BEFORE INSERT OR UPDATE OR DELETE ON public.folha_conferencia_historico FOR EACH ROW EXECUTE FUNCTION folha_privado.conferencia_historico_guardar();
CREATE CONSTRAINT TRIGGER folha_conferencia_trilho_final AFTER INSERT OR UPDATE ON public.folha_conferencias_mensais DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION folha_privado.conferencia_trilho_final();
CREATE FUNCTION folha_privado.conferencia_reconciliar() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $reconcile$
DECLARE u public.utilizadores;c public.folha_conferencias_mensais;p uuid;m date;s jsonb;before jsonb;req uuid;
BEGIN
 u:=folha_privado.ator();PERFORM pg_advisory_xact_lock(61001,1);p:=CASE WHEN TG_OP='DELETE' THEN (to_jsonb(OLD)->>'colaborador_id')::uuid ELSE (to_jsonb(NEW)->>'colaborador_id')::uuid END;
 IF TG_TABLE_NAME='colaboradores' THEN p:=NEW.id;END IF;
 IF TG_TABLE_NAME='folha_he' THEN SELECT colaborador_id INTO p FROM public.folha_registos WHERE id=coalesce((to_jsonb(NEW)->>'folha_id')::uuid,(to_jsonb(OLD)->>'folha_id')::uuid);END IF;
 FOR c IN SELECT * FROM public.folha_conferencias_mensais WHERE empresa_id=u.empresa_id AND (p IS NULL AND TG_TABLE_NAME='folha_config_empresa' OR colaborador_id=p) ORDER BY competencia,id FOR UPDATE LOOP
  PERFORM pg_advisory_xact_lock(61001,1);s:=folha_privado.conferencia_calcular(c.colaborador_id,c.competencia);IF s->>'fingerprint'=c.fingerprint THEN CONTINUE;END IF;
  before:=to_jsonb(c);req:=gen_random_uuid();
  UPDATE public.folha_conferencias_mensais SET snapshot=s,fingerprint=s->>'fingerprint',referencias=s->'references',revision=revision+1,estado='requer_revalidacao',atualizado_por=u.id,atualizado_em=now(),ultimo_request_id=req WHERE id=c.id RETURNING * INTO c;
  INSERT INTO public.folha_conferencia_historico(empresa_id,conferencia_id,revision,action,antes,depois,ator_id,request_id,reason) VALUES(u.empresa_id,c.id,c.revision,'source_change',before,to_jsonb(c),u.id,req,'Fonte alterada: '||TG_TABLE_NAME);
 END LOOP;RETURN NULL;
END $reconcile$;
CREATE TRIGGER folha_conferencia_factos AFTER INSERT OR UPDATE OR DELETE ON public.folha_registos FOR EACH ROW EXECUTE FUNCTION folha_privado.conferencia_reconciliar();
CREATE TRIGGER folha_conferencia_ausencias AFTER INSERT OR UPDATE OR DELETE ON public.ausencias FOR EACH ROW EXECUTE FUNCTION folha_privado.conferencia_reconciliar();
CREATE TRIGGER folha_conferencia_diaria AFTER INSERT OR UPDATE ON public.folha_avaliacoes_diarias FOR EACH ROW EXECUTE FUNCTION folha_privado.conferencia_reconciliar();
CREATE TRIGGER folha_conferencia_he AFTER INSERT OR UPDATE ON public.folha_he FOR EACH ROW EXECUTE FUNCTION folha_privado.conferencia_reconciliar();
CREATE TRIGGER folha_conferencia_jornada AFTER INSERT OR UPDATE ON public.folha_jornadas_individuais_versoes FOR EACH ROW EXECUTE FUNCTION folha_privado.conferencia_reconciliar();
CREATE TRIGGER folha_conferencia_cadastro AFTER UPDATE OF data_admissao,data_saida ON public.colaboradores FOR EACH ROW EXECUTE FUNCTION folha_privado.conferencia_reconciliar();
CREATE TRIGGER folha_conferencia_calendario AFTER UPDATE OF calendar_complete,calendar_validated_years,holiday_dates ON public.folha_config_empresa FOR EACH ROW EXECUTE FUNCTION folha_privado.conferencia_reconciliar();CREATE FUNCTION public.fn_folha_conferencia_v3(p_acao text,p_dados jsonb,p_confirmar boolean DEFAULT false,p_versao text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $rpc$
DECLARE u public.utilizadores;p uuid;m date;req uuid;c public.folha_conferencias_mensais;op folha_privado.operacoes;s jsonb;before jsonb;after jsonb;payload jsonb;token text;outcome jsonb;reason text;requests jsonb;
BEGIN
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;PERFORM pg_advisory_xact_lock(61001,1);u:=folha_privado.ator();SELECT * INTO u FROM public.utilizadores WHERE id=u.id AND ativo IS TRUE FOR SHARE;
 IF NOT FOUND OR NOT folha_privado.adm() THEN RAISE EXCEPTION 'PERMISSION_DENIED: conferência mensal' USING ERRCODE='42501';END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'RETRY_READ_COMMITTED' USING ERRCODE='40001';END IF;
 p:=(p_dados->>'person_id')::uuid;m:=(p_dados->>'month')::date;req:=(p_dados->>'request_id')::uuid;reason:=nullif(btrim(p_dados->>'reason'),'');
 IF p_acao IS NULL OR p_acao NOT IN('conferir','devolver','validar') OR p_dados->>'version' IS DISTINCT FROM '3' OR p_confirmar IS NULL OR req IS NULL OR m IS NULL OR NOT isfinite(m) OR extract(day FROM m) IS DISTINCT FROM 1 OR length(reason)>1000 THEN RAISE EXCEPTION 'VALIDATION_ERROR: competência';END IF;
 IF p_dados->>'work_id' IS NOT NULL OR p_dados ? 'company_id' AND p_dados->>'company_id' IS DISTINCT FROM u.empresa_id::text OR p_dados ? 'empresa_id' AND p_dados->>'empresa_id' IS DISTINCT FROM u.empresa_id::text THEN RAISE EXCEPTION 'PERMISSION_DENIED: âmbito mensal' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.colaboradores WHERE id=p AND empresa_id=u.empresa_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: colaborador' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(u.empresa_id::text||':'||p::text||':'||m::text,0));PERFORM pg_advisory_xact_lock(hashtextextended(u.empresa_id::text||':'||u.id::text||':'||req::text,0));
 payload:=jsonb_build_object('action','monthly_'||p_acao,'data',p_dados);SELECT * INTO op FROM folha_privado.operacoes WHERE empresa_id=u.empresa_id AND ator_id=u.id AND request_id=req;
 IF FOUND THEN IF op.payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',op.token);END IF;IF p_versao IS DISTINCT FROM op.token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;RETURN op.resultado;END IF;
 SELECT * INTO c FROM public.folha_conferencias_mensais WHERE empresa_id=u.empresa_id AND colaborador_id=p AND competencia=m FOR UPDATE;
 IF (p_dados->>'expected_revision')::integer IS DISTINCT FROM coalesce(c.revision,0) THEN RAISE EXCEPTION 'STALE_REVISION' USING ERRCODE='40001';END IF;
 s:=folha_privado.conferencia_calcular(p,m);before:=CASE WHEN c.id IS NULL THEN NULL ELSE to_jsonb(c) END;
 IF p_acao='validar' THEN
  IF c.id IS NULL OR c.estado<>'conferida' OR c.fingerprint IS DISTINCT FROM s->>'fingerprint' THEN RAISE EXCEPTION 'MONTHLY_FACTS_NOT_CONFERRED' USING ERRCODE='40001';END IF;
  IF (m+interval '1 month')::date>(now() AT TIME ZONE 'Europe/Lisbon')::date THEN RAISE EXCEPTION 'COMPETENCIA_EM_CURSO';END IF;
  IF jsonb_array_length(s->'pending')>0 OR jsonb_array_length(c.pedidos_correcao)>0 THEN RAISE EXCEPTION 'MONTHLY_PENDING_FACTS';END IF;
 ELSIF p_acao='devolver' THEN
  requests:=p_dados->'records';IF reason IS NULL OR jsonb_typeof(requests) IS DISTINCT FROM 'array' OR jsonb_array_length(requests) NOT BETWEEN 1 AND 124 THEN RAISE EXCEPTION 'CORRECTION_REASON_RECORDS_REQUIRED';END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(requests) x WHERE NOT EXISTS(SELECT 1 FROM public.folha_registos f WHERE f.id=(x->>'id')::uuid AND f.empresa_id=u.empresa_id AND f.colaborador_id=p AND f.data>=m AND f.data<(m+interval '1 month')::date AND f.revision=(x->>'revision')::integer)) OR EXISTS(SELECT 1 FROM jsonb_array_elements(requests) x GROUP BY x->>'id' HAVING count(*)>1) THEN RAISE EXCEPTION 'STALE_SOURCE' USING ERRCODE='40001';END IF;
 ELSE
  IF c.id IS NOT NULL AND jsonb_array_length(c.pedidos_correcao)>0 AND reason IS NULL THEN RAISE EXCEPTION 'CORRECTION_ACKNOWLEDGEMENT_REASON_REQUIRED';END IF;
  requests:='[]';
 END IF;
 after:=jsonb_build_object('state',CASE p_acao WHEN 'conferir' THEN 'conferida' WHEN 'devolver' THEN 'devolvida' ELSE 'validada_para_integracao' END,'snapshot',s,'requests',coalesce(requests,'[]'::jsonb));
 token:=encode(sha256(convert_to(jsonb_build_object('actor_id',u.id,'company_id',u.empresa_id,'payload',payload,'before',before,'after',after)::text,'UTF8')),'hex');IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',token,'preview',after);END IF;
 IF p_versao IS DISTINCT FROM token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;
 IF c.id IS NULL THEN
  INSERT INTO public.folha_conferencias_mensais(empresa_id,colaborador_id,competencia,estado,revision,referencias,snapshot,fingerprint,pedidos_correcao,criado_por,atualizado_por,ultimo_request_id)
  VALUES(u.empresa_id,p,m,after->>'state',1,s->'references',s,s->>'fingerprint',after->'requests',u.id,u.id,req) RETURNING * INTO c;
 ELSE
  UPDATE public.folha_conferencias_mensais SET estado=after->>'state',revision=revision+1,referencias=s->'references',snapshot=s,fingerprint=s->>'fingerprint',pedidos_correcao=after->'requests',validacao_fingerprint=CASE WHEN p_acao='validar' THEN s->>'fingerprint' ELSE validacao_fingerprint END,validado_por=CASE WHEN p_acao='validar' THEN u.id ELSE validado_por END,validado_em=CASE WHEN p_acao='validar' THEN now() ELSE validado_em END,atualizado_por=u.id,atualizado_em=now(),ultimo_request_id=req WHERE id=c.id RETURNING * INTO c;
 END IF;
 INSERT INTO public.folha_conferencia_historico(empresa_id,conferencia_id,revision,action,antes,depois,ator_id,request_id,reason) VALUES(u.empresa_id,c.id,c.revision,p_acao,before,to_jsonb(c),u.id,req,reason);
 outcome:=jsonb_build_object('version',3,'committed',true,'request_id',req,'revision',c.revision,'conference',to_jsonb(c),'financial_effect',false);
 INSERT INTO folha_privado.operacoes VALUES(u.empresa_id,u.id,req,payload,token,outcome,now());RETURN outcome;
END $rpc$;
CREATE OR REPLACE FUNCTION public.fn_folha_conferencia_contexto_v3(p_colaborador_id uuid,p_competencia date) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $context$
DECLARE u public.utilizadores;c public.folha_conferencias_mensais;s jsonb;history jsonb;
BEGIN
 u:=folha_privado.ator();IF NOT folha_privado.admin() OR NOT EXISTS(SELECT 1 FROM public.colaboradores WHERE id=p_colaborador_id AND empresa_id=u.empresa_id) THEN RAISE EXCEPTION 'PERMISSION_DENIED: conferência interna' USING ERRCODE='42501';END IF;
 s:=folha_privado.conferencia_calcular(p_colaborador_id,p_competencia);SELECT * INTO c FROM public.folha_conferencias_mensais WHERE empresa_id=u.empresa_id AND colaborador_id=p_colaborador_id AND competencia=p_competencia;
 SELECT coalesce(jsonb_agg(to_jsonb(h) ORDER BY h.revision),'[]') INTO history FROM public.folha_conferencia_historico h WHERE h.empresa_id=u.empresa_id AND h.conferencia_id=c.id;
 RETURN jsonb_build_object('version',3,'committed',false,'person_id',p_colaborador_id,'month',p_competencia,'snapshot',s,'conference',CASE WHEN c.id IS NULL THEN NULL ELSE to_jsonb(c) END,'history',history,'he_policy','HR-27','financial_effect',false,'conference_write_capability',folha_privado.adm(),'expected_monthly_minutes',s->'expected_minutes','expected_coverage_state',CASE WHEN (s->>'unknown_reference_days')::integer=0 THEN 'known' ELSE 'pending' END);
END $context$;
REVOKE ALL ON FUNCTION folha_privado.conferencia_calcular(uuid,date),folha_privado.conferencia_guardar(),folha_privado.conferencia_historico_guardar(),folha_privado.conferencia_trilho_final(),folha_privado.conferencia_reconciliar() FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.fn_folha_conferencia_v3(text,jsonb,boolean,text),public.fn_folha_conferencia_contexto_v3(uuid,date) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_folha_conferencia_v3(text,jsonb,boolean,text),public.fn_folha_conferencia_contexto_v3(uuid,date) TO authenticated;
DO $hours_dependencies$ BEGIN
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.ator()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='176c4fb030401fb45c89f3cd1616a9d26e9e15b691ff524a33dfc8d233c6b079' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.ator()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.obra(uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='731f5289cd29bdb7f7d69723fabb76cbb8b8e577bb474c679f991c7271d9788e' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.obra(uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.lock_dia(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b29022304f316e25dd34bae7a1e1906a0dfd72bd041a1d658338cc8394745502' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.lock_dia(uuid,date)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.local(uuid,uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='9eb2f0d8b7e52d5280f0798c48cb8ec84377281c1e13706bc066b1cf3765070b' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.local(uuid,uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_contexto_v2(date,uuid)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='e5ca6e224708a655a9c778fa6a5701b39e6c0aab8dbf0a01a87ffb77d42ea095' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner AND x.grantee<>'authenticated'::regrole)) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: public.fn_folha_contexto_v2(date,uuid)';END IF;
END $hours_dependencies$;DO $installed$ DECLARE t text;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.conferencia_calcular(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='2b027dfb87a1a34eaec3be37607563ae5b62031406522bb0b6d15e8714ba094d' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: folha_privado.conferencia_calcular(uuid,date)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.conferencia_guardar()') AND proowner='postgres'::regrole AND prosecdef=false AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='a782033837e4fd49baa2217a5e9d597e8dcd91a2df0dbd56590c3f64bca0918a' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: folha_privado.conferencia_guardar()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.conferencia_historico_guardar()') AND proowner='postgres'::regrole AND prosecdef=false AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='2d5319aa9a121cb8cf220a9468f8583f432c125262bc7310786f6e1384008175' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: folha_privado.conferencia_historico_guardar()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.conferencia_trilho_final()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='f1f505b8aa19bf6236b287e1660cc4b35ffbe17c1d1624cfc04156f65b05d19a' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: folha_privado.conferencia_trilho_final()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.conferencia_reconciliar()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='082d8c4e6773900a13966cf75a2456c7c16c30ec432946db886a2ccf84145e38' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: folha_privado.conferencia_reconciliar()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_conferencia_v3(text,jsonb,boolean,text)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='67547f357fa27ec0673d5981f91a0ba5b8df159a4778b4718d3ce1ca7297574a' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: public.fn_folha_conferencia_v3(text,jsonb,boolean,text)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_conferencia_contexto_v3(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b500968b4fd6734bc3f60f39efc6105c99e3b320cf52df7c600524149572a7cd' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: public.fn_folha_conferencia_contexto_v3(uuid,date)';END IF;
FOREACH t IN ARRAY ARRAY['public.folha_conferencias_mensais','public.folha_conferencia_historico'] LOOP
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass(t) AND relowner='postgres'::regrole AND relrowsecurity) OR EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x WHERE c.oid=to_regclass(t) AND x.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=to_regclass(t) AND attnum>0 AND NOT attisdropped AND attacl IS NOT NULL AND attacl<>'{}'::aclitem[]) OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=to_regclass(t)) THEN RAISE EXCEPTION 'MONTHLY_RLS_ACL_DRIFT: %',t;END IF;
END LOOP;
IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.folha_conferencias_mensais'::regclass AND tgname='folha_conferencia_trilho_final' AND tgenabled='O' AND tgdeferrable AND tginitdeferred AND tgfoid='folha_privado.conferencia_trilho_final()'::regprocedure) OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgname IN('folha_conferencia_factos','folha_conferencia_ausencias','folha_conferencia_diaria','folha_conferencia_he','folha_conferencia_jornada','folha_conferencia_cadastro','folha_conferencia_calendario','folha_conferencia_guardar','folha_conferencia_historico_guardar') AND tgenabled<>'O') OR (SELECT count(*) FROM pg_trigger WHERE NOT tgisinternal AND tgname LIKE 'folha_conferencia_%')<>10 THEN RAISE EXCEPTION 'MONTHLY_TRIGGER_DRIFT';END IF;
END $installed$;
DO $unused$ BEGIN IF EXISTS(SELECT 1 FROM public.folha_conferencias_mensais) OR EXISTS(SELECT 1 FROM public.folha_conferencia_historico) THEN RAISE EXCEPTION 'MONTHLY_USED_ROLLBACK_FORBIDDEN';END IF;END $unused$;
DO $data$ DECLARE r record;j jsonb;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='primeline_monthly_backup' AND nspowner='postgres'::regrole) OR EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) x WHERE n.nspname='primeline_monthly_backup' AND x.grantee<>n.nspowner) OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x WHERE n.nspname='primeline_monthly_backup' AND x.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='primeline_monthly_backup' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL AND a.attacl<>'{}'::aclitem[]) THEN RAISE EXCEPTION 'MONTHLY_BACKUP_NOT_PRIVATE';END IF;
FOR r IN SELECT * FROM primeline_monthly_backup.dados LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),''[]''::jsonb) FROM %s x',r.tabela::regclass) INTO j;IF j IS DISTINCT FROM r.linhas THEN RAISE EXCEPTION 'MONTHLY_DATA_DRIFT';END IF;END LOOP;END $data$;
SELECT 'MONTHLY_INSTALLED_NO_VALIDATION_CREATED' resultado;COMMIT;
